# Argument checks of `rep`, `eval`, `as.function`, `environment<-`, `print.default`, `as.raw` and
# `D`: the messages, the warnings and the calls they are reported against.
t <- function(e) { r <- withCallingHandlers(tryCatch(e, error = function(e) paste("error:", conditionMessage(e), "|", deparse(conditionCall(e))[1])), warning = function(w) { cat("warning:", conditionMessage(w), "|", deparse(conditionCall(w))[1], "\n"); invokeRestart("muffleWarning") }); cat(deparse(r)[1], "\n") }
cat("rep\n"); t(rep(1:2, each = -1)); t(rep(1:2, each = NA)); t(rep(1:2, each = c(2, 3))); t(rep(1:2, each = "a")); t(rep(1:2, each = 1.9)); t(rep(1:2, each = integer(0))); t(rep(1:2, each = NULL)); t(rep(1:2, each = "2")); t(rep(1:2, each = TRUE)); t(rep(1:2, each = list(2))); t(rep(integer(0), each = -1)); t(rep(1:2, each = 0)); t(rep(NULL, each = -1)); t(rep(1:2, times = -1)); t(rep(1:2, times = NA)); t(rep(1:2, length.out = -1)); t(rep(1:2, length.out = NA)); t(rep(1:2, length.out = c(1, 2))); t(rep(1:2, length.out = "a"))
cat("eval\n"); t(eval(1, c(1, 2))); t(eval(1, integer(0))); t(eval(1, 0)); t(eval(1, NA_integer_)); t(eval(1, "a")); t(eval(1, TRUE)); t(eval(quote(x), list(x = 1), 5)); t(eval(quote(x), NULL, 5)); t(eval(1, sum)); t(eval(1, 1.9)); t(evalq(1, c(1, 2))); t(eval(1, -1)); t(eval(1, 100))
cat("fun\n"); t(as.function(alist(a = , a), 1)); t(as.function(alist(a = , a), NULL)); t(as.function(1)); t(as.function(alist())); t(as.function(list(1))); t(as.function(alist(a = , a), sum)); t(as.function(alist(1, 2, a))); t({ g <- function(x) x; body(g, 1) <- 1; g }); t({ g <- function(x) x; formals(g, 1) <- alist(y = ); g }); t({ g <- function(x) x; environment(g) <- 1; g }); t({ g <- function(x) x; environment(g) <- NULL; g }); t(`environment<-`(1, globalenv()));
cat("print\n"); t(print(matrix("a"), quote = NA)); t(print("a", quote = NA)); t(print("a", quote = "x")); t(print(1, "a")); t(print(1, digits = 0)); t(print(1, digits = NA)); t(print(1, digits = c(3, 4))); t(print(1, digits = 2.9)); t(print("a", right = NA)); t(print(1, na.print = 1)); t(print(1, print.gap = -1)); t(print(1, max = -1)); t(print(1, width = 5)); t(print(1, width = "a")); t(print(1, useSource = NA)); t(print(1, digits = TRUE)); t(print(1, zero.print = 1)); t(print(1, justify = "x")); t(print(1, print.gap = "a")); t(print(1, max = NA)); t(print(1, max = "a"))
cat("raw\n"); t(as.raw(c(5, 1e300))); t(as.raw(c(5, -1))); t(as.raw("a")); t(as.raw(c(NA, 300))); t(as.raw(1e300 + 1i)); t(as.raw(c("1e300", "x", "256"))); t(as.raw(list(1e300, 2))); t(as.raw(NaN)); t(as.raw(256L)); t(as.raw(3+1i))
cat("D\n"); t(D("x^2", "x")); t(D(1, "x")); t(D(quote(x), "x")); t(D(list(1), "x")); t(D(expression(x^2), "x")); t(D(NULL, "x")); t(D(TRUE, "x")); t(D(1i, "x")); t(D(sum, "x")); t(D(quote(x^2), 1)); t(D(quote(x^2), c("x", "y"))); t(D(quote(x^2), character(0))); t(D(quote(x^2), NA_character_)); t(D(quote(foo(x)), "x"))
t(as.integer(1e300+1i)); t(as.integer(complex(real = 1, imaginary = NaN))); t(as.integer(2+1i)); t(as.integer("0x10")); t(as.integer(" 7 "))
